bench <- function(b, t) {
  r <- diff(cumsum(c(rep(FALSE, 20), b)), 20)
  if (any(r >= t)) return(tagList(span(style = "color: #4393c3;", "✓"), " reached"))
  sprintf("%.0f%%", 100 * tail(r, 1) / t)
}

dat <- function(m, type, lvl, p) {
  d <- m$model
  n <- nrow(d)
  j <- seq_len(min(3, n))
  i <- unique(c(order(-abs(residuals(m)))[j], order(-abs(rstandard(m)))[j], order(-cooks.distance(m))[j]))
  par(mar = c(5, 5, 3, 3) + 0.1)
  plot(d$x, d$y, type = "n", bty = "n", axes = FALSE, xlab = "", ylab = "")
  u <- par("usr")
  par(family = "serif")
  mtext(expression(bold(y)), 2, 3, col = p[["lab"]], las = 1, cex = par("cex"))
  mtext(expression(bold(x)), 1, 3, col = p[["lab"]], cex = par("cex"))
  par(family = "sans")
  rect(u[1], u[3], u[2], u[4], col = p[["panel"]], border = NA)
  g <- function(t) seq(t[1] - diff(t[1:2]), t[length(t)] + diff(t[1:2]), diff(t[1:2]) / 2)
  abline(h = g(axTicks(2)), v = g(axTicks(1)), lwd = 2, col = p[["bg"]])
  abline(h = axTicks(2), v = axTicks(1), lwd = 3, col = p[["bg"]])
  eaxis(1, col = p[["ax"]], col.axis = p[["ax"]], col.ticks = p[["ax"]], small.args = list(col = p[["ax"]]))
  eaxis(2, col = p[["ax"]], col.axis = p[["ax"]], col.ticks = p[["ax"]], small.args = list(col = p[["ax"]]))
  curve(mu(x, type, lvl), u[1], u[2], add = TRUE, col = p[["true"]], lwd = 3)
  abline(coef(m), col = p[["line"]], lwd = 3)
  legend("topleft", c("Fitted line", "True relationship"), col = p[c("line", "true")], lwd = 3, bty = "n")
  points(d$x, d$y, pch = 19)
  text(d$x[i], d$y[i], rownames(d)[i], pos = ifelse(d$x[i] > mean(u[1:2]), 2, 4), cex = 0.8)
}

diag4 <- function(m, p) {
  sm <- function(x, y, ...) panel.smooth(x, y, col.smooth = p[["blue"]], iter = 3, ...)
  pl <- plm(p[["zero"]])
  yl <- list("Residuals", NULL, expression(sqrt(abs("Std. residuals"))), NULL,
             "Std. residuals")
  for(i in c(1, 2, 3, 5)){
    if(i == 2){
      qq(m, p)
      next
    }
    pl(m, which = i, pch = 19, panel = sm, axes = FALSE, ann = FALSE, sub.caption = "", cook.col = p[["cook"]])
    title(ylab = yl[[i]])
    if(i == 5){
      axis(4, -5:5, rep("", 11), col = p[["bg"]], tck = 0, lwd = 3)
      title(xlab = "Leverage", line = 2)
    } else{
      title(xlab = "Fitted values", line = 2)
    }
    eaxis(1)
    eaxis(2)
  }
}

lp <- 0.83 * 0.2 * 96

ar <- c(1.6, 1.9)

sz <- function(wd, vh) {
  v <- wd < 600
  p <- if (v) wd else wd / 2
  d <- (p - 6.2 * lp) / ar[1]
  if (!v) {
    d <- max(min(d, (vh - 10) / 2 - 4.9 * lp), (300 - 6.2 * lp) / ar[2])
    p <- min(p, ar[2] * d + 6.2 * lp)
  }
  list(v = v, w = round(if (v) p else 2 * p), h = round((if (v) 4 else 2) * (d + 4.9 * lp)))
}

