    var on = this.getAttribute('data-choice') === c;
    $(this).attr('aria-checked', on ? 'true' : 'false').parent().toggleClass('active', on);
  });
  $('#dm').trigger('dmchange');
}
dmShow();
var dmB = new Shiny.InputBinding();
$.extend(dmB, {
  find: function(scope) { return $(scope).find('#dm'); },
  getValue: function() { return dmDark(); },
  subscribe: function(el, cb) { $(el).on('dmchange.dm', function() { cb(); }); },
  unsubscribe: function(el) { $(el).off('.dm'); }
});
Shiny.inputBindings.register(dmB, 'dm');
$(dmShow);
$(document).on('click', '#dm .dropdown-menu a', function(e) {
  e.preventDefault();
  var c = this.getAttribute('data-choice');
  try { if (c === 'system') localStorage.removeItem(dmK); else localStorage.setItem(dmK, c === 'dark' ? 'alternate' : 'default'); } catch (x) {}
  dmShow();
});
window.addEventListener('storage', function(e) { if (e.key === dmK || e.key === null) dmShow(); });
if (dmQ.addEventListener) dmQ.addEventListener('change', dmShow); else if (dmQ.addListener) dmQ.addListener(dmShow);
